'use client';

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import apiClient from '@/lib/api/client';
import type {
  Cluster,
  ClusterHealth,
  ClusterStats,
  ClusterNode,
  ClusterSettings,
  Shard,
  ApiResponse,
} from '@/types';

// ========================================
// Query Keys
// ========================================

export const clusterKeys = {
  all: ['clusters'] as const,
  lists: () => [...clusterKeys.all, 'list'] as const,
  list: (filters: string) => [...clusterKeys.lists(), { filters }] as const,
  details: () => [...clusterKeys.all, 'detail'] as const,
  detail: (id: string) => [...clusterKeys.details(), id] as const,
  health: (clusterId: string) => [...clusterKeys.all, 'health', clusterId] as const,
  stats: (clusterId: string) => [...clusterKeys.all, 'stats', clusterId] as const,
  nodes: (clusterId: string) => [...clusterKeys.all, 'nodes', clusterId] as const,
  settings: (clusterId: string) => [...clusterKeys.all, 'settings', clusterId] as const,
  shards: (clusterId: string) => [...clusterKeys.all, 'shards', clusterId] as const,
};

// ========================================
// Types for Mutations
// ========================================

export interface CreateClusterPayload {
  name: string;
  scheme: 'http' | 'https';
  host: string;
  port: number;
  username?: string;
  password?: string;
  kibana?: string;
  theme: number;
  dictCluster?: string;
}

export interface UpdateClusterPayload extends Partial<CreateClusterPayload> {
  id: string;
}

export interface TestConnectionPayload {
  scheme: 'http' | 'https';
  host: string;
  port: number;
  username?: string;
  password?: string;
}

export interface TestConnectionResponse {
  success: boolean;
  nodeCount?: number;
  clusterName?: string;
  error?: string;
}

// ========================================
// Queries
// ========================================

/**
 * Fetch all clusters
 */
export function useClusters() {
  return useQuery({
    queryKey: clusterKeys.lists(),
    queryFn: async () => {
      const { data } = await apiClient.get<ApiResponse<Cluster[]>>('/clusters');
      return data.data ?? [];
    },
  });
}

/**
 * Fetch single cluster detail
 */
export function useCluster(clusterId: string) {
  return useQuery({
    queryKey: clusterKeys.detail(clusterId),
    queryFn: async () => {
      const { data } = await apiClient.get<ApiResponse<Cluster>>(`/clusters/${clusterId}`);
      return data.data;
    },
    enabled: !!clusterId,
  });
}

/**
 * Fetch cluster health - GET /_cluster/health
 */
export function useClusterHealth(clusterId: string) {
  return useQuery({
    queryKey: clusterKeys.health(clusterId),
    queryFn: async () => {
      const { data } = await apiClient.get<ClusterHealth>(`/es/${clusterId}/_cluster/health`);
      return data;
    },
    enabled: !!clusterId,
    refetchInterval: 30000, // Refresh every 30 seconds
  });
}

/**
 * Fetch cluster stats - GET /_cluster/stats
 */
export function useClusterStats(clusterId: string) {
  return useQuery({
    queryKey: clusterKeys.stats(clusterId),
    queryFn: async () => {
      const { data } = await apiClient.get<ClusterStats>(`/es/${clusterId}/_cluster/stats`);
      return data;
    },
    enabled: !!clusterId,
    refetchInterval: 30000,
  });
}

/**
 * Fetch cluster nodes - GET /_nodes
 */
export function useClusterNodes(clusterId: string) {
  return useQuery({
    queryKey: clusterKeys.nodes(clusterId),
    queryFn: async () => {
      const { data } = await apiClient.get<ApiResponse<ClusterNode[]>>(`/es/${clusterId}/_nodes`);
      return data.data ?? [];
    },
    enabled: !!clusterId,
    refetchInterval: 30000,
  });
}

/**
 * Fetch cluster settings - GET /_cluster/settings
 */
export function useClusterSettings(clusterId: string, includeDefaults: boolean = false) {
  return useQuery({
    queryKey: clusterKeys.settings(clusterId),
    queryFn: async () => {
      const params = includeDefaults ? '?include_defaults=true' : '';
      const { data } = await apiClient.get<ClusterSettings>(
        `/es/${clusterId}/_cluster/settings${params}`
      );
      return data;
    },
    enabled: !!clusterId,
  });
}

/**
 * Fetch shards - GET /_cat/shards
 */
export function useShards(clusterId: string, indexFilter?: string) {
  return useQuery({
    queryKey: [...clusterKeys.shards(clusterId), indexFilter] as const,
    queryFn: async () => {
      const params = indexFilter ? `?index=${indexFilter}` : '';
      const { data } = await apiClient.get<ApiResponse<Shard[]>>(
        `/es/${clusterId}/_cat/shards${params}`
      );
      return data.data ?? [];
    },
    enabled: !!clusterId,
    refetchInterval: 30000,
  });
}

// ========================================
// Mutations
// ========================================

/**
 * Test cluster connection
 */
export function useTestConnection() {
  return useMutation({
    mutationFn: async (payload: TestConnectionPayload) => {
      const { data } = await apiClient.post<TestConnectionResponse>(
        '/clusters/test-connection',
        payload
      );
      return data;
    },
  });
}

/**
 * Create new cluster
 */
export function useCreateCluster() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (payload: CreateClusterPayload) => {
      const { data } = await apiClient.post<ApiResponse<Cluster>>('/clusters', payload);
      return data.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: clusterKeys.lists() });
    },
  });
}

/**
 * Update existing cluster
 */
export function useUpdateCluster() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ id, ...payload }: UpdateClusterPayload) => {
      const { data } = await apiClient.put<ApiResponse<Cluster>>(`/clusters/${id}`, payload);
      return data.data;
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: clusterKeys.lists() });
      queryClient.invalidateQueries({ queryKey: clusterKeys.detail(variables.id) });
    },
  });
}

/**
 * Delete cluster
 */
export function useDeleteCluster() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ id, includeData }: { id: string; includeData?: boolean }) => {
      const params = includeData ? '?include_data=true' : '';
      await apiClient.delete(`/clusters/${id}${params}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: clusterKeys.lists() });
    },
  });
}

/**
 * Update cluster settings
 */
export function useUpdateClusterSettings() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      clusterId,
      settings,
    }: {
      clusterId: string;
      settings: Partial<ClusterSettings>;
    }) => {
      const { data } = await apiClient.put<ClusterSettings>(
        `/es/${clusterId}/_cluster/settings`,
        settings
      );
      return data;
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: clusterKeys.settings(variables.clusterId) });
    },
  });
}

/**
 * Set server check status
 */
export function useSetServerCheck() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ clusterId, checking }: { clusterId: string; checking: boolean }) => {
      const { data } = await apiClient.post<ApiResponse<void>>(
        `/clusters/${clusterId}/server-check`,
        { checking }
      );
      return data;
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: clusterKeys.detail(variables.clusterId) });
      queryClient.invalidateQueries({ queryKey: clusterKeys.lists() });
    },
  });
}

