# Frontend Integration Plan: Dictionary API for search-admin-ui

## Executive Summary

This plan outlines the comprehensive frontend integration strategy for connecting `search-admin-ui` to the `search-admin` backend's Dictionary API (`/api/v1/dictionary`). The design follows existing codebase patterns discovered in `use-cluster.ts` and `use-analysis.ts`.

---

## 1. File Structure

```
src/
├── types/
│   └── dictionary.ts           # New: Dictionary-specific types
├── hooks/
│   └── use-dictionary.ts       # New: React Query hooks for Dictionary API
├── stores/
│   └── dictionary.store.ts     # New: Zustand store for UI state
└── lib/
    └── api/
        └── dictionary.api.ts   # New: API functions (optional, can be inline)
```

---

## 2. TypeScript Types (`src/types/dictionary.ts`)

```typescript
// ========================================
// Dictionary Types for Backend API v1
// ========================================

/**
 * Available dictionary types from the backend
 */
export type DictionaryTypeV1 =
  | 'ENGLISH'
  | 'SYNONYM'
  | 'USER'
  | 'SPACE'
  | 'COMPOUND'
  | 'UNIT'
  | 'UNIT_SYNONYM'
  | 'STOP';

/**
 * Core dictionary entity matching backend DTO
 */
export interface DictionaryEntry {
  keyword: string;
  type: DictionaryTypeV1;
  value: string;
  createdTime?: string;
  updatedTime?: string;
}

/**
 * Dictionary with ID wrapper (response format)
 */
export interface DictionaryWithId {
  id: number;
  dictionary: DictionaryEntry;
}

/**
 * Compile result from backend
 */
export interface CompileResult {
  type: DictionaryTypeV1;
  count: number;
  filePath: string;
  fileSize: number;
}

/**
 * Paginated response from backend
 */
export interface DictionaryPageResponse {
  content: DictionaryWithId[];
  totalElements: number;
  totalPages: number;
  size: number;
  number: number;  // current page (0-based)
  first: boolean;
  last: boolean;
  empty: boolean;
}

/**
 * Request payload for creating dictionary entry
 */
export interface CreateDictionaryPayload {
  keyword: string;
  type: DictionaryTypeV1;
  value: string;
}

/**
 * Request payload for updating dictionary entry
 */
export interface UpdateDictionaryPayload {
  keyword: string;
  type: DictionaryTypeV1;
  value: string;
}

/**
 * Search parameters
 */
export interface DictionarySearchParams {
  word: string;
  isMatch?: boolean;  // exact match vs contains
}

/**
 * List parameters
 */
export interface DictionaryListParams {
  type: DictionaryTypeV1;
  page?: number;
  size?: number;
}

// ========================================
// UI-specific types
// ========================================

/**
 * Flattened dictionary for UI consumption
 */
export interface DictionaryRow {
  id: number;
  keyword: string;
  type: DictionaryTypeV1;
  value: string;
  createdTime?: string;
  updatedTime?: string;
}

/**
 * Type metadata for UI display
 */
export interface DictionaryTypeInfo {
  type: DictionaryTypeV1;
  label: string;
  description: string;
  category: 'SET' | 'SYNONYM' | 'MAP';
  hasKeyword: boolean;
}

export const DICTIONARY_TYPE_INFO: Record<DictionaryTypeV1, DictionaryTypeInfo> = {
  ENGLISH: {
    type: 'ENGLISH',
    label: 'English Words',
    description: 'English vocabulary dictionary',
    category: 'SET',
    hasKeyword: false,
  },
  SYNONYM: {
    type: 'SYNONYM',
    label: 'Synonyms',
    description: 'Word synonym mappings',
    category: 'SYNONYM',
    hasKeyword: true,
  },
  USER: {
    type: 'USER',
    label: 'User Dictionary',
    description: 'Custom user-defined words',
    category: 'SET',
    hasKeyword: false,
  },
  SPACE: {
    type: 'SPACE',
    label: 'Space Separation',
    description: 'Words to separate by space',
    category: 'MAP',
    hasKeyword: true,
  },
  COMPOUND: {
    type: 'COMPOUND',
    label: 'Compound Words',
    description: 'Compound word decomposition',
    category: 'MAP',
    hasKeyword: true,
  },
  UNIT: {
    type: 'UNIT',
    label: 'Units',
    description: 'Unit words dictionary',
    category: 'SET',
    hasKeyword: false,
  },
  UNIT_SYNONYM: {
    type: 'UNIT_SYNONYM',
    label: 'Unit Synonyms',
    description: 'Unit synonym mappings',
    category: 'SYNONYM',
    hasKeyword: true,
  },
  STOP: {
    type: 'STOP',
    label: 'Stop Words',
    description: 'Words to ignore during analysis',
    category: 'SET',
    hasKeyword: false,
  },
};
```

---

## 3. React Query Hooks (`src/hooks/use-dictionary.ts`)

```typescript
'use client';

import { useQuery, useMutation, useQueryClient, keepPreviousData } from '@tanstack/react-query';
import apiClient from '@/lib/api/client';
import type {
  DictionaryTypeV1,
  DictionaryWithId,
  DictionaryPageResponse,
  CreateDictionaryPayload,
  UpdateDictionaryPayload,
  CompileResult,
  DictionaryRow,
} from '@/types/dictionary';

// ========================================
// Query Keys Factory
// ========================================

export const dictionaryKeys = {
  all: ['dictionary'] as const,

  // List queries
  lists: () => [...dictionaryKeys.all, 'list'] as const,
  list: (type: DictionaryTypeV1, page: number, size: number) =>
    [...dictionaryKeys.lists(), type, { page, size }] as const,

  // Search queries
  searches: () => [...dictionaryKeys.all, 'search'] as const,
  search: (type: DictionaryTypeV1, word: string, isMatch: boolean) =>
    [...dictionaryKeys.searches(), type, { word, isMatch }] as const,

  // Compile status
  compile: () => [...dictionaryKeys.all, 'compile'] as const,
  compileByType: (type: DictionaryTypeV1) =>
    [...dictionaryKeys.compile(), type] as const,
};

// ========================================
// Helper: Transform response to UI format
// ========================================

function transformToRow(item: DictionaryWithId): DictionaryRow {
  return {
    id: item.id,
    keyword: item.dictionary.keyword,
    type: item.dictionary.type,
    value: item.dictionary.value,
    createdTime: item.dictionary.createdTime,
    updatedTime: item.dictionary.updatedTime,
  };
}

// ========================================
// LIST Query
// ========================================

interface UseDictionaryListParams {
  type: DictionaryTypeV1;
  page?: number;
  size?: number;
  enabled?: boolean;
}

export function useDictionaryList({
  type,
  page = 0,
  size = 20,
  enabled = true,
}: UseDictionaryListParams) {
  return useQuery({
    queryKey: dictionaryKeys.list(type, page, size),
    queryFn: async () => {
      const { data } = await apiClient.get<DictionaryPageResponse>(
        `/api/v1/dictionary/${type}`,
        { params: { page, size } }
      );
      return {
        ...data,
        items: data.content.map(transformToRow),
      };
    },
    enabled: enabled && !!type,
    staleTime: 30_000, // 30 seconds
    placeholderData: keepPreviousData, // Keep previous data while fetching new page
  });
}

// ========================================
// SEARCH Query
// ========================================

interface UseDictionarySearchParams {
  type: DictionaryTypeV1;
  word: string;
  isMatch?: boolean;
  enabled?: boolean;
}

export function useDictionarySearch({
  type,
  word,
  isMatch = true,
  enabled = true,
}: UseDictionarySearchParams) {
  return useQuery({
    queryKey: dictionaryKeys.search(type, word, isMatch),
    queryFn: async () => {
      const { data } = await apiClient.get<DictionaryWithId[]>(
        `/api/v1/dictionary/${type}/search`,
        { params: { word, isMatch } }
      );
      return data.map(transformToRow);
    },
    enabled: enabled && !!type && !!word && word.length >= 1,
    staleTime: 30_000,
  });
}

// ========================================
// CREATE Mutation
// ========================================

export function useCreateDictionary() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (payload: CreateDictionaryPayload) => {
      const { data } = await apiClient.post<DictionaryWithId>(
        '/api/v1/dictionary',
        payload
      );
      return data;
    },
    onSuccess: (_, variables) => {
      // Invalidate list for the affected type
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.lists(),
        predicate: (query) => {
          const key = query.queryKey as unknown[];
          return key[2] === variables.type;
        },
      });
      // Invalidate all searches for this type
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.searches(),
      });
    },
  });
}

// ========================================
// UPDATE Mutation
// ========================================

interface UpdateDictionaryParams extends UpdateDictionaryPayload {
  id: number;
}

export function useUpdateDictionary() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ id, ...payload }: UpdateDictionaryParams) => {
      const { data } = await apiClient.put<DictionaryWithId>(
        `/api/v1/dictionary/${id}`,
        payload
      );
      return data;
    },
    onSuccess: (_, variables) => {
      // Invalidate list queries
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.lists(),
      });
      // Invalidate search queries
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.searches(),
      });
    },
    // Optimistic update for better UX
    onMutate: async (variables) => {
      // Cancel outgoing refetches
      await queryClient.cancelQueries({
        queryKey: dictionaryKeys.lists(),
      });

      // Snapshot current state for rollback
      const previousData = queryClient.getQueriesData({
        queryKey: dictionaryKeys.lists(),
      });

      return { previousData };
    },
    onError: (err, variables, context) => {
      // Rollback on error
      if (context?.previousData) {
        context.previousData.forEach(([queryKey, data]) => {
          queryClient.setQueryData(queryKey, data);
        });
      }
    },
  });
}

// ========================================
// DELETE Mutation
// ========================================

interface DeleteDictionaryParams {
  id: number;
  type: DictionaryTypeV1;
}

export function useDeleteDictionary() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ id }: DeleteDictionaryParams) => {
      await apiClient.delete(`/api/v1/dictionary/${id}`);
    },
    onSuccess: (_, variables) => {
      // Invalidate list for affected type
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.lists(),
      });
      // Invalidate search queries
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.searches(),
      });
    },
    // Optimistic delete
    onMutate: async (variables) => {
      await queryClient.cancelQueries({
        queryKey: dictionaryKeys.lists(),
      });

      const previousData = queryClient.getQueriesData({
        queryKey: dictionaryKeys.lists(),
      });

      // Optimistically remove from cache
      queryClient.setQueriesData(
        { queryKey: dictionaryKeys.lists() },
        (old: any) => {
          if (!old?.items) return old;
          return {
            ...old,
            items: old.items.filter((item: DictionaryRow) => item.id !== variables.id),
            totalElements: old.totalElements - 1,
          };
        }
      );

      return { previousData };
    },
    onError: (err, variables, context) => {
      if (context?.previousData) {
        context.previousData.forEach(([queryKey, data]) => {
          queryClient.setQueryData(queryKey, data);
        });
      }
    },
  });
}

// ========================================
// BULK DELETE Mutation
// ========================================

interface BulkDeleteParams {
  ids: number[];
  type: DictionaryTypeV1;
}

export function useBulkDeleteDictionary() {
  const queryClient = useQueryClient();
  const deleteMutation = useDeleteDictionary();

  return useMutation({
    mutationFn: async ({ ids }: BulkDeleteParams) => {
      // Sequential deletion (backend doesn't support bulk delete)
      const results = await Promise.allSettled(
        ids.map((id) => apiClient.delete(`/api/v1/dictionary/${id}`))
      );

      const failed = results.filter((r) => r.status === 'rejected');
      if (failed.length > 0) {
        throw new Error(`Failed to delete ${failed.length} items`);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.lists(),
      });
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.searches(),
      });
    },
  });
}

// ========================================
// COMPILE Single Type Mutation
// ========================================

export function useCompileDictionaryType() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (type: DictionaryTypeV1) => {
      const { data } = await apiClient.post<CompileResult>(
        `/api/v1/dictionary/compile/${type}`
      );
      return data;
    },
    onSuccess: (data, type) => {
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.compileByType(type),
      });
    },
  });
}

// ========================================
// COMPILE All Types Mutation
// ========================================

export function useCompileAllDictionaries() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async () => {
      const { data } = await apiClient.post<CompileResult[]>(
        '/api/v1/dictionary/compile'
      );
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.compile(),
      });
    },
  });
}

// ========================================
// Prefetch Utilities
// ========================================

export function usePrefetchDictionaryList() {
  const queryClient = useQueryClient();

  return (type: DictionaryTypeV1, page = 0, size = 20) => {
    queryClient.prefetchQuery({
      queryKey: dictionaryKeys.list(type, page, size),
      queryFn: async () => {
        const { data } = await apiClient.get<DictionaryPageResponse>(
          `/api/v1/dictionary/${type}`,
          { params: { page, size } }
        );
        return {
          ...data,
          items: data.content.map(transformToRow),
        };
      },
      staleTime: 30_000,
    });
  };
}

// ========================================
// Infinite Query for Virtual Scrolling
// ========================================

export function useDictionaryInfinite({
  type,
  size = 20,
  enabled = true,
}: {
  type: DictionaryTypeV1;
  size?: number;
  enabled?: boolean;
}) {
  return useInfiniteQuery({
    queryKey: [...dictionaryKeys.lists(), type, 'infinite'] as const,
    queryFn: async ({ pageParam = 0 }) => {
      const { data } = await apiClient.get<DictionaryPageResponse>(
        `/api/v1/dictionary/${type}`,
        { params: { page: pageParam, size } }
      );
      return {
        ...data,
        items: data.content.map(transformToRow),
      };
    },
    initialPageParam: 0,
    getNextPageParam: (lastPage) => {
      if (lastPage.last) return undefined;
      return lastPage.number + 1;
    },
    enabled: enabled && !!type,
    staleTime: 30_000,
  });
}

// Need to import useInfiniteQuery
import { useInfiniteQuery } from '@tanstack/react-query';
```

---

## 4. Zustand Store (`src/stores/dictionary.store.ts`)

```typescript
import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { DictionaryTypeV1, DictionaryRow } from '@/types/dictionary';

interface DictionaryUIState {
  // Active dictionary type
  selectedType: DictionaryTypeV1;
  setSelectedType: (type: DictionaryTypeV1) => void;

  // Pagination state
  currentPage: number;
  pageSize: number;
  setPage: (page: number) => void;
  setPageSize: (size: number) => void;

  // Search state
  searchQuery: string;
  isExactMatch: boolean;
  setSearchQuery: (query: string) => void;
  setIsExactMatch: (isMatch: boolean) => void;
  clearSearch: () => void;

  // Selection state (for bulk operations)
  selectedIds: Set<number>;
  selectItem: (id: number) => void;
  deselectItem: (id: number) => void;
  selectAll: (ids: number[]) => void;
  clearSelection: () => void;
  isSelected: (id: number) => boolean;

  // Modal/Dialog state
  isCreateDialogOpen: boolean;
  isEditDialogOpen: boolean;
  isDeleteDialogOpen: boolean;
  isCompileDialogOpen: boolean;
  editingItem: DictionaryRow | null;
  openCreateDialog: () => void;
  openEditDialog: (item: DictionaryRow) => void;
  openDeleteDialog: () => void;
  openCompileDialog: () => void;
  closeAllDialogs: () => void;

  // Reset all state
  reset: () => void;
}

const initialState = {
  selectedType: 'USER' as DictionaryTypeV1,
  currentPage: 0,
  pageSize: 20,
  searchQuery: '',
  isExactMatch: true,
  selectedIds: new Set<number>(),
  isCreateDialogOpen: false,
  isEditDialogOpen: false,
  isDeleteDialogOpen: false,
  isCompileDialogOpen: false,
  editingItem: null as DictionaryRow | null,
};

export const useDictionaryStore = create<DictionaryUIState>()(
  persist(
    (set, get) => ({
      ...initialState,

      setSelectedType: (type) => set({
        selectedType: type,
        currentPage: 0,
        selectedIds: new Set(),
        searchQuery: '',
      }),

      setPage: (page) => set({ currentPage: page }),
      setPageSize: (size) => set({ pageSize: size, currentPage: 0 }),

      setSearchQuery: (query) => set({ searchQuery: query, currentPage: 0 }),
      setIsExactMatch: (isMatch) => set({ isExactMatch: isMatch }),
      clearSearch: () => set({ searchQuery: '', currentPage: 0 }),

      selectItem: (id) => set((state) => {
        const newSet = new Set(state.selectedIds);
        newSet.add(id);
        return { selectedIds: newSet };
      }),
      deselectItem: (id) => set((state) => {
        const newSet = new Set(state.selectedIds);
        newSet.delete(id);
        return { selectedIds: newSet };
      }),
      selectAll: (ids) => set({ selectedIds: new Set(ids) }),
      clearSelection: () => set({ selectedIds: new Set() }),
      isSelected: (id) => get().selectedIds.has(id),

      openCreateDialog: () => set({ isCreateDialogOpen: true }),
      openEditDialog: (item) => set({ isEditDialogOpen: true, editingItem: item }),
      openDeleteDialog: () => set({ isDeleteDialogOpen: true }),
      openCompileDialog: () => set({ isCompileDialogOpen: true }),
      closeAllDialogs: () => set({
        isCreateDialogOpen: false,
        isEditDialogOpen: false,
        isDeleteDialogOpen: false,
        isCompileDialogOpen: false,
        editingItem: null,
      }),

      reset: () => set(initialState),
    }),
    {
      name: 'dictionary-ui-storage',
      partialize: (state) => ({
        selectedType: state.selectedType,
        pageSize: state.pageSize,
      }),
    }
  )
);
```

---

## 5. Usage Examples

### Basic List with Pagination

```typescript
'use client';

import { useDictionaryList } from '@/hooks/use-dictionary';
import { useDictionaryStore } from '@/stores/dictionary.store';

export function DictionaryTable() {
  const { selectedType, currentPage, pageSize, setPage } = useDictionaryStore();

  const { data, isLoading, error, isFetching } = useDictionaryList({
    type: selectedType,
    page: currentPage,
    size: pageSize,
  });

  if (isLoading) return <TableSkeleton />;
  if (error) return <ErrorAlert error={error} />;

  return (
    <div>
      {isFetching && <LoadingOverlay />}
      <Table data={data?.items ?? []} />
      <Pagination
        currentPage={currentPage}
        totalPages={data?.totalPages ?? 0}
        onPageChange={setPage}
      />
    </div>
  );
}
```

### Search with Debounce

```typescript
'use client';

import { useState, useDeferredValue } from 'react';
import { useDictionarySearch } from '@/hooks/use-dictionary';
import { useDictionaryStore } from '@/stores/dictionary.store';

export function DictionarySearch() {
  const { selectedType, isExactMatch } = useDictionaryStore();
  const [inputValue, setInputValue] = useState('');
  const deferredSearch = useDeferredValue(inputValue);

  const { data, isLoading } = useDictionarySearch({
    type: selectedType,
    word: deferredSearch,
    isMatch: isExactMatch,
    enabled: deferredSearch.length >= 1,
  });

  return (
    <div>
      <Input
        value={inputValue}
        onChange={(e) => setInputValue(e.target.value)}
        placeholder="Search dictionary..."
      />
      {isLoading ? <Spinner /> : <SearchResults results={data} />}
    </div>
  );
}
```

### CRUD Operations

```typescript
'use client';

import { useCreateDictionary, useUpdateDictionary, useDeleteDictionary } from '@/hooks/use-dictionary';
import { useDictionaryStore } from '@/stores/dictionary.store';
import { toast } from 'sonner';

export function DictionaryForm() {
  const { selectedType, editingItem, closeAllDialogs } = useDictionaryStore();

  const createMutation = useCreateDictionary();
  const updateMutation = useUpdateDictionary();
  const deleteMutation = useDeleteDictionary();

  const handleCreate = async (formData: { keyword: string; value: string }) => {
    try {
      await createMutation.mutateAsync({
        keyword: formData.keyword,
        type: selectedType,
        value: formData.value,
      });
      toast.success('Dictionary entry created');
      closeAllDialogs();
    } catch (error) {
      toast.error('Failed to create entry');
    }
  };

  const handleUpdate = async (formData: { keyword: string; value: string }) => {
    if (!editingItem) return;

    try {
      await updateMutation.mutateAsync({
        id: editingItem.id,
        keyword: formData.keyword,
        type: selectedType,
        value: formData.value,
      });
      toast.success('Dictionary entry updated');
      closeAllDialogs();
    } catch (error) {
      toast.error('Failed to update entry');
    }
  };

  const handleDelete = async () => {
    if (!editingItem) return;

    try {
      await deleteMutation.mutateAsync({
        id: editingItem.id,
        type: selectedType,
      });
      toast.success('Dictionary entry deleted');
      closeAllDialogs();
    } catch (error) {
      toast.error('Failed to delete entry');
    }
  };

  // ... form JSX
}
```

### Compile Operations

```typescript
'use client';

import { useCompileDictionaryType, useCompileAllDictionaries } from '@/hooks/use-dictionary';
import { useDictionaryStore } from '@/stores/dictionary.store';
import { toast } from 'sonner';

export function CompileControls() {
  const { selectedType } = useDictionaryStore();

  const compileSingleMutation = useCompileDictionaryType();
  const compileAllMutation = useCompileAllDictionaries();

  const handleCompileSingle = async () => {
    try {
      const result = await compileSingleMutation.mutateAsync(selectedType);
      toast.success(`Compiled ${result.count} entries to ${result.filePath}`);
    } catch (error) {
      toast.error('Failed to compile dictionary');
    }
  };

  const handleCompileAll = async () => {
    try {
      const results = await compileAllMutation.mutateAsync();
      const totalCount = results.reduce((sum, r) => sum + r.count, 0);
      toast.success(`Compiled ${totalCount} total entries`);
    } catch (error) {
      toast.error('Failed to compile dictionaries');
    }
  };

  return (
    <div className="flex gap-2">
      <Button
        onClick={handleCompileSingle}
        disabled={compileSingleMutation.isPending}
      >
        {compileSingleMutation.isPending ? 'Compiling...' : `Compile ${selectedType}`}
      </Button>
      <Button
        onClick={handleCompileAll}
        disabled={compileAllMutation.isPending}
        variant="outline"
      >
        {compileAllMutation.isPending ? 'Compiling...' : 'Compile All'}
      </Button>
    </div>
  );
}
```

---

## 6. Query Invalidation Strategy

| Action | Invalidate | Rationale |
|--------|-----------|-----------|
| Create | `lists` (same type), `searches` | New entry affects list and search results |
| Update | `lists` (all), `searches` | Entry might change type |
| Delete | `lists` (all), `searches` | Remove from all cached queries |
| Compile | `compile`, `compileByType` | Update compile status |

---

## 7. Error Handling Strategy

```typescript
// src/lib/api/error-handler.ts
import { AxiosError } from 'axios';

export interface ApiError {
  status: number;
  message: string;
  code?: string;
  details?: Record<string, string>;
}

export function parseApiError(error: unknown): ApiError {
  if (error instanceof AxiosError) {
    const response = error.response;

    if (response) {
      return {
        status: response.status,
        message: response.data?.message || response.statusText,
        code: response.data?.code,
        details: response.data?.details,
      };
    }

    if (error.code === 'ECONNABORTED') {
      return {
        status: 408,
        message: 'Request timeout',
        code: 'TIMEOUT',
      };
    }

    return {
      status: 0,
      message: 'Network error',
      code: 'NETWORK_ERROR',
    };
  }

  return {
    status: 500,
    message: 'Unknown error',
    code: 'UNKNOWN',
  };
}

// Usage in mutations
export function useCreateDictionary() {
  return useMutation({
    mutationFn: async (payload) => {
      // ...
    },
    onError: (error) => {
      const apiError = parseApiError(error);

      switch (apiError.status) {
        case 400:
          toast.error('Invalid dictionary data');
          break;
        case 409:
          toast.error('Dictionary entry already exists');
          break;
        case 500:
          toast.error('Server error. Please try again.');
          break;
        default:
          toast.error(apiError.message);
      }
    },
  });
}
```

---

## 8. Performance Optimizations

### 1. Prefetching on Hover
```typescript
// Prefetch next page when user hovers pagination
const prefetch = usePrefetchDictionaryList();

<PaginationButton
  onMouseEnter={() => prefetch(selectedType, currentPage + 1, pageSize)}
>
  Next
</PaginationButton>
```

### 2. Stale Time Configuration
- List queries: 30 seconds (data changes frequently)
- Search queries: 30 seconds (same rationale)
- Compile status: 60 seconds (changes less often)

### 3. Window Focus Refetching
```typescript
// In QueryClient configuration
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      refetchOnWindowFocus: true,  // Refetch stale data on focus
      refetchOnMount: true,
      retry: 2,
    },
  },
});
```

---

## 9. Type Export Updates (`src/types/index.ts`)

Add to existing types file:

```typescript
// ========================================
// Dictionary V1 Types (re-export)
// ========================================

export type {
  DictionaryTypeV1,
  DictionaryEntry,
  DictionaryWithId,
  DictionaryPageResponse,
  CompileResult,
  CreateDictionaryPayload,
  UpdateDictionaryPayload,
  DictionarySearchParams,
  DictionaryListParams,
  DictionaryRow,
  DictionaryTypeInfo,
} from './dictionary';

export { DICTIONARY_TYPE_INFO } from './dictionary';
```

---

## 10. Implementation Checklist

- [ ] Create `src/types/dictionary.ts` with all type definitions
- [ ] Create `src/hooks/use-dictionary.ts` with React Query hooks
- [ ] Create `src/stores/dictionary.store.ts` with Zustand store
- [ ] Update `src/types/index.ts` to re-export dictionary types
- [ ] Add error handler utility if not exists
- [ ] Create UI components that consume these hooks
- [ ] Write unit tests for hooks
- [ ] Write integration tests for API calls

---

## Architecture Decisions

### Why React Query over Zustand for Server State?
- React Query handles caching, background refetching, and stale data automatically
- Zustand is better suited for UI state (selections, dialogs, filters)
- Clear separation: React Query = server state, Zustand = client state

### Why Query Key Factory Pattern?
- Type-safe query keys
- Easy invalidation with `queryKey: dictionaryKeys.lists()`
- Hierarchical structure enables partial invalidation

### Why Optimistic Updates?
- Better perceived performance for delete operations
- Immediate feedback to user
- Automatic rollback on failure

### Why keepPreviousData for Pagination?
- Prevents UI flash when changing pages
- User sees old data while new data loads
- Smoother pagination experience

