## 3. React Query Hooks (`src/hooks/use-dictionary.ts`)

```typescript
'use client';

import { useQuery, useMutation, useQueryClient, keepPreviousData } from '@tanstack/react-query';
import apiClient from '@/lib/api/client';
import type {
  DictionaryTypeV1,
  DictionaryWithId,
  DictionaryPageResponse,
  CreateDictionaryPayload,
  UpdateDictionaryPayload,
  CompileResult,
  DictionaryRow,
} from '@/types/dictionary';

// ========================================
// Query Keys Factory
// ========================================

export const dictionaryKeys = {
  all: ['dictionary'] as const,

  // List queries
  lists: () => [...dictionaryKeys.all, 'list'] as const,
  list: (type: DictionaryTypeV1, page: number, size: number) =>
    [...dictionaryKeys.lists(), type, { page, size }] as const,

  // Search queries
  searches: () => [...dictionaryKeys.all, 'search'] as const,
  search: (type: DictionaryTypeV1, word: string, isMatch: boolean) =>
    [...dictionaryKeys.searches(), type, { word, isMatch }] as const,

  // Compile status
  compile: () => [...dictionaryKeys.all, 'compile'] as const,
  compileByType: (type: DictionaryTypeV1) =>
    [...dictionaryKeys.compile(), type] as const,
};

// ========================================
// Helper: Transform response to UI format
// ========================================

function transformToRow(item: DictionaryWithId): DictionaryRow {
  return {
    id: item.id,
    keyword: item.dictionary.keyword,
    type: item.dictionary.type,
    value: item.dictionary.value,
    createdTime: item.dictionary.createdTime,
    updatedTime: item.dictionary.updatedTime,
  };
}

// ========================================
// LIST Query
// ========================================

interface UseDictionaryListParams {
  type: DictionaryTypeV1;
  page?: number;
  size?: number;
  enabled?: boolean;
}

export function useDictionaryList({
  type,
  page = 0,
  size = 20,
  enabled = true,
}: UseDictionaryListParams) {
  return useQuery({
    queryKey: dictionaryKeys.list(type, page, size),
    queryFn: async () => {
      const { data } = await apiClient.get<DictionaryPageResponse>(
        `/api/v1/dictionary/${type}`,
        { params: { page, size } }
      );
      return {
        ...data,
        items: data.content.map(transformToRow),
      };
    },
    enabled: enabled && !!type,
    staleTime: 30_000, // 30 seconds
    placeholderData: keepPreviousData, // Keep previous data while fetching new page
  });
}

// ========================================
// SEARCH Query
// ========================================

interface UseDictionarySearchParams {
  type: DictionaryTypeV1;
  word: string;
  isMatch?: boolean;
  enabled?: boolean;
}

export function useDictionarySearch({
  type,
  word,
  isMatch = true,
  enabled = true,
}: UseDictionarySearchParams) {
  return useQuery({
    queryKey: dictionaryKeys.search(type, word, isMatch),
    queryFn: async () => {
      const { data } = await apiClient.get<DictionaryWithId[]>(
        `/api/v1/dictionary/${type}/search`,
        { params: { word, isMatch } }
      );
      return data.map(transformToRow);
    },
    enabled: enabled && !!type && !!word && word.length >= 1,
    staleTime: 30_000,
  });
}

// ========================================
// CREATE Mutation
// ========================================

export function useCreateDictionary() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (payload: CreateDictionaryPayload) => {
      const { data } = await apiClient.post<DictionaryWithId>(
        '/api/v1/dictionary',
        payload
      );
      return data;
    },
    onSuccess: (_, variables) => {
      // Invalidate list for the affected type
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.lists(),
        predicate: (query) => {
          const key = query.queryKey as unknown[];
          return key[2] === variables.type;
        },
      });
      // Invalidate all searches for this type
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.searches(),
      });
    },
  });
}

// ========================================
// UPDATE Mutation
// ========================================

interface UpdateDictionaryParams extends UpdateDictionaryPayload {
  id: number;
}

export function useUpdateDictionary() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ id, ...payload }: UpdateDictionaryParams) => {
      const { data } = await apiClient.put<DictionaryWithId>(
        `/api/v1/dictionary/${id}`,
        payload
      );
      return data;
    },
    onSuccess: (_, variables) => {
      // Invalidate list queries
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.lists(),
      });
      // Invalidate search queries
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.searches(),
      });
    },
    // Optimistic update for better UX
    onMutate: async (variables) => {
      // Cancel outgoing refetches
      await queryClient.cancelQueries({
        queryKey: dictionaryKeys.lists(),
      });

      // Snapshot current state for rollback
      const previousData = queryClient.getQueriesData({
        queryKey: dictionaryKeys.lists(),
      });

      return { previousData };
    },
    onError: (err, variables, context) => {
      // Rollback on error
      if (context?.previousData) {
        context.previousData.forEach(([queryKey, data]) => {
          queryClient.setQueryData(queryKey, data);
        });
      }
    },
  });
}

// ========================================
// DELETE Mutation
// ========================================

interface DeleteDictionaryParams {
  id: number;
  type: DictionaryTypeV1;
}

export function useDeleteDictionary() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ id }: DeleteDictionaryParams) => {
      await apiClient.delete(`/api/v1/dictionary/${id}`);
    },
    onSuccess: (_, variables) => {
      // Invalidate list for affected type
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.lists(),
      });
      // Invalidate search queries
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.searches(),
      });
    },
    // Optimistic delete
    onMutate: async (variables) => {
      await queryClient.cancelQueries({
        queryKey: dictionaryKeys.lists(),
      });

      const previousData = queryClient.getQueriesData({
        queryKey: dictionaryKeys.lists(),
      });

      // Optimistically remove from cache
      queryClient.setQueriesData(
        { queryKey: dictionaryKeys.lists() },
        (old: any) => {
          if (!old?.items) return old;
          return {
            ...old,
            items: old.items.filter((item: DictionaryRow) => item.id !== variables.id),
            totalElements: old.totalElements - 1,
          };
        }
      );

      return { previousData };
    },
    onError: (err, variables, context) => {
      if (context?.previousData) {
        context.previousData.forEach(([queryKey, data]) => {
          queryClient.setQueryData(queryKey, data);
        });
      }
    },
  });
}

// ========================================
// BULK DELETE Mutation
// ========================================

interface BulkDeleteParams {
  ids: number[];
  type: DictionaryTypeV1;
}

export function useBulkDeleteDictionary() {
  const queryClient = useQueryClient();
  const deleteMutation = useDeleteDictionary();

  return useMutation({
    mutationFn: async ({ ids }: BulkDeleteParams) => {
      // Sequential deletion (backend doesn't support bulk delete)
      const results = await Promise.allSettled(
        ids.map((id) => apiClient.delete(`/api/v1/dictionary/${id}`))
      );

      const failed = results.filter((r) => r.status === 'rejected');
      if (failed.length > 0) {
        throw new Error(`Failed to delete ${failed.length} items`);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.lists(),
      });
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.searches(),
      });
    },
  });
}

// ========================================
// COMPILE Single Type Mutation
// ========================================

export function useCompileDictionaryType() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (type: DictionaryTypeV1) => {
      const { data } = await apiClient.post<CompileResult>(
        `/api/v1/dictionary/compile/${type}`
      );
      return data;
    },
    onSuccess: (data, type) => {
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.compileByType(type),
      });
    },
  });
}

// ========================================
// COMPILE All Types Mutation
// ========================================

export function useCompileAllDictionaries() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async () => {
      const { data } = await apiClient.post<CompileResult[]>(
        '/api/v1/dictionary/compile'
      );
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.compile(),
      });
    },
  });
}

// ========================================
// Prefetch Utilities
// ========================================

export function usePrefetchDictionaryList() {
  const queryClient = useQueryClient();

  return (type: DictionaryTypeV1, page = 0, size = 20) => {
    queryClient.prefetchQuery({
      queryKey: dictionaryKeys.list(type, page, size),
      queryFn: async () => {
        const { data } = await apiClient.get<DictionaryPageResponse>(
          `/api/v1/dictionary/${type}`,
          { params: { page, size } }
        );
        return {
          ...data,
          items: data.content.map(transformToRow),
        };
      },
      staleTime: 30_000,
    });
  };
}

// ========================================
// Infinite Query for Virtual Scrolling
// ========================================

export function useDictionaryInfinite({
  type,
  size = 20,
  enabled = true,
}: {
  type: DictionaryTypeV1;
  size?: number;
  enabled?: boolean;
}) {
  return useInfiniteQuery({
    queryKey: [...dictionaryKeys.lists(), type, 'infinite'] as const,
    queryFn: async ({ pageParam = 0 }) => {
      const { data } = await apiClient.get<DictionaryPageResponse>(
        `/api/v1/dictionary/${type}`,
        { params: { page: pageParam, size } }
      );
      return {
        ...data,
        items: data.content.map(transformToRow),
      };
    },
    initialPageParam: 0,
    getNextPageParam: (lastPage) => {
      if (lastPage.last) return undefined;
      return lastPage.number + 1;
    },
    enabled: enabled && !!type,
    staleTime: 30_000,
  });
}

// Need to import useInfiniteQuery
import { useInfiniteQuery } from '@tanstack/react-query';
```

