## 4. Zustand Store (`src/stores/dictionary.store.ts`)

```typescript
import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { DictionaryTypeV1, DictionaryRow } from '@/types/dictionary';

interface DictionaryUIState {
  // Active dictionary type
  selectedType: DictionaryTypeV1;
  setSelectedType: (type: DictionaryTypeV1) => void;

  // Pagination state
  currentPage: number;
  pageSize: number;
  setPage: (page: number) => void;
  setPageSize: (size: number) => void;

  // Search state
  searchQuery: string;
  isExactMatch: boolean;
  setSearchQuery: (query: string) => void;
  setIsExactMatch: (isMatch: boolean) => void;
  clearSearch: () => void;

  // Selection state (for bulk operations)
  selectedIds: Set<number>;
  selectItem: (id: number) => void;
  deselectItem: (id: number) => void;
  selectAll: (ids: number[]) => void;
  clearSelection: () => void;
  isSelected: (id: number) => boolean;

  // Modal/Dialog state
  isCreateDialogOpen: boolean;
  isEditDialogOpen: boolean;
  isDeleteDialogOpen: boolean;
  isCompileDialogOpen: boolean;
  editingItem: DictionaryRow | null;
  openCreateDialog: () => void;
  openEditDialog: (item: DictionaryRow) => void;
  openDeleteDialog: () => void;
  openCompileDialog: () => void;
  closeAllDialogs: () => void;

  // Reset all state
  reset: () => void;
}

const initialState = {
  selectedType: 'USER' as DictionaryTypeV1,
  currentPage: 0,
  pageSize: 20,
  searchQuery: '',
  isExactMatch: true,
  selectedIds: new Set<number>(),
  isCreateDialogOpen: false,
  isEditDialogOpen: false,
  isDeleteDialogOpen: false,
  isCompileDialogOpen: false,
  editingItem: null as DictionaryRow | null,
};

export const useDictionaryStore = create<DictionaryUIState>()(
  persist(
    (set, get) => ({
      ...initialState,

      setSelectedType: (type) => set({
        selectedType: type,
        currentPage: 0,
        selectedIds: new Set(),
        searchQuery: '',
      }),

      setPage: (page) => set({ currentPage: page }),
      setPageSize: (size) => set({ pageSize: size, currentPage: 0 }),

      setSearchQuery: (query) => set({ searchQuery: query, currentPage: 0 }),
      setIsExactMatch: (isMatch) => set({ isExactMatch: isMatch }),
      clearSearch: () => set({ searchQuery: '', currentPage: 0 }),

      selectItem: (id) => set((state) => {
        const newSet = new Set(state.selectedIds);
        newSet.add(id);
        return { selectedIds: newSet };
      }),
      deselectItem: (id) => set((state) => {
        const newSet = new Set(state.selectedIds);
        newSet.delete(id);
        return { selectedIds: newSet };
      }),
      selectAll: (ids) => set({ selectedIds: new Set(ids) }),
      clearSelection: () => set({ selectedIds: new Set() }),
      isSelected: (id) => get().selectedIds.has(id),

      openCreateDialog: () => set({ isCreateDialogOpen: true }),
      openEditDialog: (item) => set({ isEditDialogOpen: true, editingItem: item }),
      openDeleteDialog: () => set({ isDeleteDialogOpen: true }),
      openCompileDialog: () => set({ isCompileDialogOpen: true }),
      closeAllDialogs: () => set({
        isCreateDialogOpen: false,
        isEditDialogOpen: false,
        isDeleteDialogOpen: false,
        isCompileDialogOpen: false,
        editingItem: null,
      }),

      reset: () => set(initialState),
    }),
    {
      name: 'dictionary-ui-storage',
      partialize: (state) => ({
        selectedType: state.selectedType,
        pageSize: state.pageSize,
      }),
    }
  )
);
```

