### Compile Operations

```typescript
'use client';

import { useCompileDictionaryType, useCompileAllDictionaries } from '@/hooks/use-dictionary';
import { useDictionaryStore } from '@/stores/dictionary.store';
import { toast } from 'sonner';

export function CompileControls() {
  const { selectedType } = useDictionaryStore();

  const compileSingleMutation = useCompileDictionaryType();
  const compileAllMutation = useCompileAllDictionaries();

  const handleCompileSingle = async () => {
    try {
      const result = await compileSingleMutation.mutateAsync(selectedType);
      toast.success(`Compiled ${result.count} entries to ${result.filePath}`);
    } catch (error) {
      toast.error('Failed to compile dictionary');
    }
  };

  const handleCompileAll = async () => {
    try {
      const results = await compileAllMutation.mutateAsync();
      const totalCount = results.reduce((sum, r) => sum + r.count, 0);
      toast.success(`Compiled ${totalCount} total entries`);
    } catch (error) {
      toast.error('Failed to compile dictionaries');
    }
  };

  return (
    <div className="flex gap-2">
      <Button
        onClick={handleCompileSingle}
        disabled={compileSingleMutation.isPending}
      >
        {compileSingleMutation.isPending ? 'Compiling...' : `Compile ${selectedType}`}
      </Button>
      <Button
        onClick={handleCompileAll}
        disabled={compileAllMutation.isPending}
        variant="outline"
      >
        {compileAllMutation.isPending ? 'Compiling...' : 'Compile All'}
      </Button>
    </div>
  );
}
